import{_ as s,c as a,o as i,a2 as r}from"./chunks/framework.Cqt7uvsz.js";const u=JSON.parse('{"title":"Node.js Buffer","description":"","frontmatter":{},"headers":[],"relativePath":"front-end-learning/engineering/node/base/buffer.md","filePath":"front-end-learning/engineering/node/base/buffer.md","lastUpdated":1766579221000}'),l={name:"front-end-learning/engineering/node/base/buffer.md"};function n(f,e,t,p,h,o){return i(),a("div",null,e[0]||(e[0]=[r(`<h1 id="node-js-buffer" tabindex="-1">Node.js Buffer <a class="header-anchor" href="#node-js-buffer" aria-label="Permalink to &quot;Node.js Buffer&quot;">​</a></h1><p><a href="http://dev.nodejs.cn/learn/nodejs-buffers" target="_blank" rel="noreferrer">参考</a></p><ul><li><a href="#-buffer">什么是 buffer？</a></li><li><a href="#-buffer">为什么需要 buffer？</a></li><li><a href="#-buffer">如何创建 buffer</a></li><li><a href="#-buffer">使用 buffer</a></li></ul><h2 id="什么是-buffer" tabindex="-1">什么是 buffer？ <a class="header-anchor" href="#什么是-buffer" aria-label="Permalink to &quot;什么是 buffer？&quot;">​</a></h2><p>Buffer 是内存区域。 JavaScript 开发者可能对这个概念并不熟悉，比每天与内存交互的 C、C++ 或 Go 开发者（或使用系统编程语言的任何程序员）要少得多。</p><p><strong>它表示在 V8 JavaScript 引擎外部分配的固定大小的内存块（无法调整大小）。</strong></p><p><strong>可以将 buffer 视为整数数组，每个整数代表一个数据字节。</strong></p><p>它由 Node.js Buffer 类实现。</p><h2 id="为什么需要-buffer" tabindex="-1">为什么需要 buffer？ <a class="header-anchor" href="#为什么需要-buffer" aria-label="Permalink to &quot;为什么需要 buffer？&quot;">​</a></h2><p>Buffer 被引入用以帮助开发者处理二进制数据，在此生态系统中传统上只处理字符串而不是二进制数据。</p><p>Buffer 与流紧密相连。 当流处理器接收数据的速度快于其消化的速度时，则会将数据放入 buffer 中。</p><p>一个简单的场景是：当观看 YouTube 视频时，红线超过了观看点：即下载数据的速度比查看数据的速度快，且浏览器会对数据进行缓冲。</p><h2 id="如何创建-buffer" tabindex="-1">如何创建 buffer <a class="header-anchor" href="#如何创建-buffer" aria-label="Permalink to &quot;如何创建 buffer&quot;">​</a></h2><p>使用 <code>Buffer.from()</code>、<code>Buffer.alloc()</code> 和 <code>Buffer.allocUnsafe()</code> 方法可以创建 buffer。</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> buf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Buffer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Hey!&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>Buffer.from(array)</code></li><li><code>Buffer.from(arrayBuffer[, byteOffset[, length]])</code></li><li><code>Buffer.from(buffer)</code></li><li><code>Buffer.from(string[, encoding])</code></li></ul><p>也可以只初始化 buffer（传入大小）。 以下会创建一个 1KB 的 buffer</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> buf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Buffer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">alloc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//或</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> buf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Buffer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">allocUnsafe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>alloc 和 allocUnsafe 均分配指定大小的 Buffer（以字节为单位），但是 alloc 创建的 Buffer 会被使用零进行初始化，而 allocUnsafe 创建的 Buffer 不会被初始化。 这意味着，尽管 allocUnsafe 比 alloc 要快得多，但是分配的内存片段可能包含可能敏感的旧数据。</p></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>当 Buffer 内存被读取时，如果内存中存在较旧的数据，则可以被访问或泄漏。 这就是真正使 allocUnsafe 不安全的原因，在使用它时必须格外小心。</p></div><h2 id="使用-buffer" tabindex="-1">使用 buffer <a class="header-anchor" href="#使用-buffer" aria-label="Permalink to &quot;使用 buffer&quot;">​</a></h2><p><a href="http://dev.nodejs.cn/learn/nodejs-buffers#%E4%BD%BF%E7%94%A8-buffer" target="_blank" rel="noreferrer">详情</a></p><ul><li>访问 buffer 的内容</li><li>获取 buffer 的长度</li><li>迭代 buffer 的内容</li><li>更改 buffer 的内容</li><li>复制 buffer</li><li>切片 buffer</li></ul>`,23)]))}const c=s(l,[["render",n]]);export{u as __pageData,c as default};
